    const sh=sheetFor(p,p.stage);if(!sh.signature?.data)return toast('请先上传本人签字图片');if(sh.submitted||!canHandle(p))return;sh.total=scoreTotal(sh);sh.submitted=true;sh.at=new Date().toLocaleString('zh-CN',{hour12:false});record(p,'专家评分已提交',sh.comment,{expert:state.expert,internalOnly:true});if(p.stage==='meeting'&&summary(p,'meeting').completed.length===summary(p,'meeting').total){record(p,'线下专家会议评审已完成','全体专家已提交评审意见，进入省文旅厅复审。');p.stage='hall';}save();closeModal();navigate('projects');toast('评分与签字已提交，返回项目列表');return;
